import { createClient, Session, SupabaseClient } from "@supabase/supabase-js";
import { IStorage } from "../types";

declare let __SUPABASE_URL__: string;
declare let __SUPABASE_ANON_KEY__: string;
declare let __COMMIT_HASH__: string;

const STORAGE_SNAPSHOTS_TABLE = "storage_snapshots";
const PROFILES_TABLE = "profiles";
const AUTH_STORAGE_KEY = "praxon-supabase-auth";

let supabaseClient: SupabaseClient | undefined;

export interface IPraxonCloudSnapshot {
  user_id: string;
  email: string | null;
  storage: IStorage;
  last_synced_storage: IStorage | null;
  storage_version: string | null;
  device_id: string | null;
  app_version: string | null;
  created_at: string;
  updated_at: string;
}

export interface IPraxonCloudProfile {
  user_id: string;
  email: string | null;
  nickname: string | null;
  created_at: string;
  updated_at: string;
}

export interface IPraxonCloudAccountState {
  configured: boolean;
  session: Session | null;
  profile: IPraxonCloudProfile | null;
  latestSnapshot: IPraxonCloudSnapshot | null;
}

function getSupabaseUrl(): string | undefined {
  return __SUPABASE_URL__ || undefined;
}

function getSupabaseAnonKey(): string | undefined {
  return __SUPABASE_ANON_KEY__ || undefined;
}

function requireSupabaseClient(): SupabaseClient {
  const client = PraxonCloud_getClient();
  if (client == null) {
    throw new Error("Supabase is not configured. Set SUPABASE_URL and SUPABASE_ANON_KEY.");
  }
  return client;
}

function getRedirectUrl(): string {
  const url = new URL(window.location.href);
  url.searchParams.set("cloud", "1");
  return url.toString();
}

async function requireSession(): Promise<Session> {
  const session = await PraxonCloud_getSession();
  if (session == null) {
    throw new Error("Sign in to Praxon Cloud first.");
  }
  return session;
}

export function PraxonCloud_isConfigured(): boolean {
  return !!getSupabaseUrl() && !!getSupabaseAnonKey();
}

export function PraxonCloud_getClient(): SupabaseClient | undefined {
  const url = getSupabaseUrl();
  const anonKey = getSupabaseAnonKey();
  if (!url || !anonKey) {
    return undefined;
  }
  if (supabaseClient == null) {
    supabaseClient = createClient(url, anonKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true,
        storageKey: AUTH_STORAGE_KEY,
      },
    });
  }
  return supabaseClient;
}

export async function PraxonCloud_getSession(): Promise<Session | null> {
  const client = PraxonCloud_getClient();
  if (client == null) {
    return null;
  }
  const { data, error } = await client.auth.getSession();
  if (error) {
    throw error;
  }
  return data.session;
}

export function PraxonCloud_onAuthStateChange(
  cb: (session: Session | null) => void
): { unsubscribe: () => void } | undefined {
  const client = PraxonCloud_getClient();
  if (client == null) {
    return undefined;
  }
  const { data } = client.auth.onAuthStateChange((_event, session) => cb(session));
  return data.subscription;
}

export async function PraxonCloud_sendMagicLink(email: string): Promise<void> {
  const client = requireSupabaseClient();
  const { error } = await client.auth.signInWithOtp({
    email,
    options: {
      emailRedirectTo: getRedirectUrl(),
    },
  });
  if (error) {
    throw error;
  }
}

export async function PraxonCloud_signOut(): Promise<void> {
  const client = requireSupabaseClient();
  const { error } = await client.auth.signOut();
  if (error) {
    throw error;
  }
}

export async function PraxonCloud_uploadSnapshot(args: {
  storage: IStorage;
  lastSyncedStorage?: IStorage;
  deviceId?: string;
}): Promise<IPraxonCloudSnapshot> {
  const client = requireSupabaseClient();
  const session = await requireSession();
  const payload = {
    user_id: session.user.id,
    email: session.user.email ?? null,
    storage: args.storage,
    last_synced_storage: args.lastSyncedStorage ?? null,
    storage_version: args.storage.version ?? null,
    device_id: args.deviceId ?? null,
    app_version: __COMMIT_HASH__ ?? null,
  };
  const { data, error } = await client
    .from(STORAGE_SNAPSHOTS_TABLE)
    .upsert(payload, { onConflict: "user_id" })
    .select()
    .single();
  if (error) {
    throw error;
  }
  return data as IPraxonCloudSnapshot;
}

export async function PraxonCloud_getLatestSnapshot(): Promise<IPraxonCloudSnapshot | null> {
  const client = requireSupabaseClient();
  const session = await requireSession();
  const { data, error } = await client
    .from(STORAGE_SNAPSHOTS_TABLE)
    .select("*")
    .eq("user_id", session.user.id)
    .maybeSingle();
  if (error) {
    throw error;
  }
  return (data as IPraxonCloudSnapshot | null) ?? null;
}

export async function PraxonCloud_getProfile(): Promise<IPraxonCloudProfile | null> {
  const client = requireSupabaseClient();
  const session = await requireSession();
  const { data, error } = await client
    .from(PROFILES_TABLE)
    .select("*")
    .eq("user_id", session.user.id)
    .maybeSingle();
  if (error) {
    throw error;
  }
  return (data as IPraxonCloudProfile | null) ?? null;
}

export async function PraxonCloud_upsertProfile(args: {
  email?: string;
  nickname?: string;
}): Promise<IPraxonCloudProfile> {
  const client = requireSupabaseClient();
  const session = await requireSession();
  const payload = {
    user_id: session.user.id,
    email: args.email ?? session.user.email ?? null,
    nickname: args.nickname ?? null,
  };
  const { data, error } = await client.from(PROFILES_TABLE).upsert(payload, { onConflict: "user_id" }).select().single();
  if (error) {
    throw error;
  }
  return data as IPraxonCloudProfile;
}

export async function PraxonCloud_getAccountState(): Promise<IPraxonCloudAccountState> {
  if (!PraxonCloud_isConfigured()) {
    return {
      configured: false,
      session: null,
      profile: null,
      latestSnapshot: null,
    };
  }

  const session = await PraxonCloud_getSession();
  if (session == null) {
    return {
      configured: true,
      session: null,
      profile: null,
      latestSnapshot: null,
    };
  }

  const [profile, latestSnapshot] = await Promise.all([PraxonCloud_getProfile(), PraxonCloud_getLatestSnapshot()]);
  return {
    configured: true,
    session,
    profile,
    latestSnapshot,
  };
}
